BEGIN;
INSERT INTO clinic_assistant.patients ("Id","TenantId","Name","Phone","Email","BirthDate","ConsentStatus","Source","CreatedAt","UpdatedAt")
SELECT ('00000000-0000-0000-0000-' || lpad((30+n)::text,12,'0'))::uuid, '00000000-0000-0000-0000-000000000001'::uuid, 'Paciente Minimal ' || n, '+5500000000' || lpad(n::text,2,'0'), 'paciente.minimal.' || n || '@fake.local', '1990-01-01'::date + n, 'Granted', 'Manual', '2026-08-03T12:00:00Z'::timestamptz, '2026-08-03T12:00:00Z'::timestamptz FROM generate_series(1,5) AS n
ON CONFLICT ("Id") DO UPDATE SET "UpdatedAt"=EXCLUDED."UpdatedAt";
INSERT INTO clinic_assistant.availability_rules ("Id","TenantId","ProfessionalId","DayOfWeek","StartTime","EndTime","SlotDurationMinutes","Active","CreatedAt","UpdatedAt")
SELECT ('00000000-0000-0000-0000-' || lpad((40+n)::text,12,'0'))::uuid, '00000000-0000-0000-0000-000000000001'::uuid, CASE WHEN n%2=0 THEN '00000000-0000-0000-0000-000000000026'::uuid ELSE '00000000-0000-0000-0000-000000000025'::uuid END, n%7, '08:00'::time, '13:00'::time, 30, true, '2026-08-03T12:00:00Z'::timestamptz, '2026-08-03T12:00:00Z'::timestamptz FROM generate_series(1,10) AS n
ON CONFLICT ("Id") DO UPDATE SET "UpdatedAt"=EXCLUDED."UpdatedAt";
INSERT INTO clinic_assistant.whatsapp_integrations ("Id","TenantId","Provider","IntegrationKey","WhatsAppFrom","DisplayPhoneNumber","Status","ConnectedAt","CreatedAt","UpdatedAt") VALUES
('00000000-0000-0000-0000-000000000051','00000000-0000-0000-0000-000000000001',:'whatsapp_provider',CASE WHEN :'whatsapp_provider' = 'Twilio' THEN :'twilio_integration_key' ELSE 'fake-minimal' END,CASE WHEN :'whatsapp_provider' = 'Twilio' THEN :'twilio_whatsapp_from' ELSE 'whatsapp:+5500000000000' END,CASE WHEN :'whatsapp_provider' = 'Twilio' THEN :'twilio_display_phone_number' ELSE 'Fake Minimal Sender' END,'Connected','2026-08-03T12:00:00Z','2026-08-03T12:00:00Z','2026-08-03T12:00:00Z') ON CONFLICT ("Id") DO UPDATE SET "Provider"=EXCLUDED."Provider", "IntegrationKey"=EXCLUDED."IntegrationKey", "WhatsAppFrom"=EXCLUDED."WhatsAppFrom", "DisplayPhoneNumber"=EXCLUDED."DisplayPhoneNumber", "Status"=EXCLUDED."Status", "ConnectedAt"=EXCLUDED."ConnectedAt", "UpdatedAt"=EXCLUDED."UpdatedAt";
INSERT INTO clinic_assistant.appointments ("Id","TenantId","ClinicUnitId","ProfessionalId","SpecialtyId","PatientId","StartsAt","EndsAt","Status","Source","Notes","CreatedAt","UpdatedAt")
SELECT ('00000000-0000-0000-0000-' || lpad((60+n)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000001'::uuid,'00000000-0000-0000-0000-000000000022'::uuid,CASE WHEN n%2=0 THEN '00000000-0000-0000-0000-000000000026'::uuid ELSE '00000000-0000-0000-0000-000000000025'::uuid END,CASE WHEN n%2=0 THEN '00000000-0000-0000-0000-000000000024'::uuid ELSE '00000000-0000-0000-0000-000000000023'::uuid END,('00000000-0000-0000-0000-' || lpad((30+n)::text,12,'0'))::uuid,('2026-08-03'::date+n+time '09:00')::timestamp AT TIME ZONE 'America/Recife',('2026-08-03'::date+n+time '09:30')::timestamp AT TIME ZONE 'America/Recife',CASE WHEN n=1 THEN 'Pending' WHEN n=2 THEN 'Confirmed' ELSE 'Cancelled' END,'Dashboard','Consulta fictícia minimal','2026-08-03T12:00:00Z','2026-08-03T12:00:00Z' FROM generate_series(1,3) AS n
ON CONFLICT ("Id") DO UPDATE SET "Status"=EXCLUDED."Status", "UpdatedAt"=EXCLUDED."UpdatedAt";
INSERT INTO clinic_assistant.conversations ("Id","TenantId","PatientId","Channel","IntegrationId","Status","StartedAt","AutomationMode","Priority","Version","CreatedAt","UpdatedAt") VALUES
('00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000031','WhatsApp','00000000-0000-0000-0000-000000000051','Bot','2026-08-03T12:00:00Z','Automated','Normal',1,'2026-08-03T12:00:00Z','2026-08-03T12:00:00Z'),
('00000000-0000-0000-0000-000000000072','00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000032','WhatsApp','00000000-0000-0000-0000-000000000051','WaitingHuman','2026-08-03T12:00:00Z','Human','High',1,'2026-08-03T12:00:00Z','2026-08-03T12:00:00Z') ON CONFLICT ("Id") DO UPDATE SET "UpdatedAt"=EXCLUDED."UpdatedAt";
COMMIT;
